from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
import asyncio

app = FastAPI()

class MyCallable:
    def __call__(self, q: str = "default"):
        return q

async def async_dep(q: str = "default"):
    return q

@app.get("/callable")
def read_callable(q: str = Depends(functools.partial(MyCallable(), q="world"))):
    return q

@app.get("/async")
async def read_async(q: str = Depends(functools.partial(async_dep, q="world"))):
    return q

client = TestClient(app)

def test_callable():
    response = client.get("/callable")
    print(f"Callable response: {response.json()}")
    assert response.json() == "world"

def test_async():
    response = client.get("/async")
    print(f"Async response: {response.json()}")
    assert response.json() == "world"

if __name__ == "__main__":
    try:
        test_callable()
        print("Callable test passed")
    except Exception as e:
        print(f"Callable test failed: {e}")

    try:
        test_async()
        print("Async test passed")
    except Exception as e:
        print(f"Async test failed: {e}")

