import asyncio
from functools import partial
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
from typing import Annotated

async def async_dep(q: str = "default"):
    return q

class CallableDep:
    def __call__(self, q: str = "default"):
        return q

class AsyncCallableDep:
    async def __call__(self, q: str = "default"):
        return q

app = FastAPI()

@app.get("/async-partial")
async def read_async_partial(dep: Annotated[str, Depends(partial(async_dep, q="world"))]):
    return {"response": dep}

@app.get("/callable-partial")
async def read_callable_partial(dep: Annotated[str, Depends(partial(CallableDep(), q="world"))]):
    return {"response": dep}

@app.get("/async-callable-partial")
async def read_async_callable_partial(dep: Annotated[str, Depends(partial(AsyncCallableDep(), q="world"))]):
    return {"response": dep}

client = TestClient(app)

def test_async_partial():
    response = client.get("/async-partial")
    print(f"Async partial: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"response": "world"}

def test_callable_partial():
    response = client.get("/callable-partial")
    print(f"Callable partial: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"response": "world"}

def test_async_callable_partial():
    response = client.get("/async-callable-partial")
    print(f"Async callable partial: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"response": "world"}

if __name__ == "__main__":
    try:
        test_async_partial()
        print("test_async_partial passed")
        test_callable_partial()
        print("test_callable_partial passed")
        test_async_callable_partial()
        print("test_async_callable_partial passed")
        print("All tests passed!")
